package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){String id=a.length>0?a[0]:"2";try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();Flower f=s.get(Flower.class,id);if(f==null){System.out.println("Error: No Flower found with id "+id);t.rollback();}else{s.remove(f);t.commit();System.out.println("Flower deleted successfully.");}}HibernateUtil.getSessionFactory().close();}}